export const landingHtml: string = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Wild Willows — a cozy nature-restoration game</title>\n<meta name=\"description\" content=\"Wild Willows is a cozy nature-restoration game: gather materials, craft and plant real habitat, and watch 150 real animals return to six living biomes. Gentle and accessible, in English and Spanish, with no combat and full offline play. On the Mac App Store, itch.io, and free in your browser.\">\n<link rel=\"canonical\" href=\"https://wild.willows.harperfabric.com/\">\n<meta name=\"robots\" content=\"index, follow, max-image-preview:large\">\n<meta name=\"theme-color\" content=\"#324528\">\n<meta name=\"author\" content=\"Bailey Dunning\">\n<meta name=\"keywords\" content=\"Wild Willows, cozy game, nature restoration game, wildlife game, relaxing game, wholesome game, life sim, ecology game, animals, no combat, offline game, accessible game, Spanish, Mac App Store, itch.io\">\n<link rel=\"icon\" type=\"image/svg+xml\" href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'%3E%3Ccircle cx='12' cy='12' r='11' fill='%234a7c59'/%3E%3Cpath d='M7 17C7 10.5 11 7.5 17 7.2c.3 6-2.7 10-10 9.8' fill='%23d8eec2'/%3E%3C/svg%3E\">\n<link rel=\"apple-touch-icon\" href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'%3E%3Ccircle cx='12' cy='12' r='11' fill='%234a7c59'/%3E%3Cpath d='M7 17C7 10.5 11 7.5 17 7.2c.3 6-2.7 10-10 9.8' fill='%23d8eec2'/%3E%3C/svg%3E\">\n<link rel=\"mask-icon\" href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'%3E%3Ccircle cx='12' cy='12' r='11' fill='%234a7c59'/%3E%3Cpath d='M7 17C7 10.5 11 7.5 17 7.2c.3 6-2.7 10-10 9.8' fill='%23d8eec2'/%3E%3C/svg%3E\" color=\"#4a7c59\">\n\n<meta property=\"og:type\" content=\"website\">\n<meta property=\"og:site_name\" content=\"Wild Willows\">\n<meta property=\"og:title\" content=\"Wild Willows — a cozy nature-restoration game\">\n<meta property=\"og:description\" content=\"Bring a broken wild place back to life — one plant, one pond, one animal at a time. 150 real animals, six living biomes, no combat, works offline. English &amp; Spanish.\">\n<meta property=\"og:url\" content=\"https://wild.willows.harperfabric.com/\">\n<meta property=\"og:image\" content=\"https://wild.willows.harperfabric.com/og-image.jpg\">\n<meta property=\"og:image:width\" content=\"1200\">\n<meta property=\"og:image:height\" content=\"630\">\n<meta property=\"og:image:alt\" content=\"A restored wetland in Wild Willows, full of water, plants, and returning animals.\">\n<meta name=\"twitter:card\" content=\"summary_large_image\">\n<meta name=\"twitter:title\" content=\"Wild Willows — a cozy nature-restoration game\">\n<meta name=\"twitter:description\" content=\"Bring a broken wild place back to life — one plant, one pond, one animal at a time. 150 real animals, six living biomes, no combat, works offline.\">\n<meta name=\"twitter:image\" content=\"https://wild.willows.harperfabric.com/og-image.jpg\">\n\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Fredoka:wght@400;500;600;700&family=Quicksand:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n\n<script type=\"application/ld+json\">\n{\n  \"@context\": \"https://schema.org\",\n  \"@graph\": [\n    {\n      \"@type\": \"VideoGame\",\n      \"name\": \"Wild Willows\",\n      \"url\": \"https://wild.willows.harperfabric.com/\",\n      \"image\": \"https://wild.willows.harperfabric.com/og-image.jpg\",\n      \"description\": \"A cozy nature-restoration life sim. Gather fallen materials, craft and plant real habitat, and shape the land biome by biome as 150 real animal species return to a recovering nature preserve. No combat and no way to fail.\",\n      \"genre\": [\"Simulation\", \"Casual\", \"Life simulation\", \"Cozy\"],\n      \"gamePlatform\": [\"macOS\", \"Windows\", \"Linux\", \"Web browser\"],\n      \"operatingSystem\": \"macOS, Windows, Linux\",\n      \"applicationCategory\": \"GameApplication\",\n      \"contentRating\": \"Apple 9+\",\n      \"inLanguage\": [\"en\", \"es\"],\n      \"availableLanguage\": [\"English\", \"Spanish\"],\n      \"author\": { \"@type\": \"Person\", \"name\": \"Bailey Dunning\" },\n      \"publisher\": { \"@type\": \"Person\", \"name\": \"Bailey Dunning\" },\n      \"offers\": [\n        { \"@type\": \"Offer\", \"url\": \"https://apps.apple.com/us/app/wild-willows/id6787300760?mt=12\", \"category\": \"Mac App Store\", \"availability\": \"https://schema.org/InStock\" },\n        { \"@type\": \"Offer\", \"url\": \"https://bai13y.itch.io/wild-willows\", \"category\": \"itch.io\", \"availability\": \"https://schema.org/InStock\" }\n      ]\n    },\n    { \"@type\": \"WebSite\", \"name\": \"Wild Willows\", \"url\": \"https://wild.willows.harperfabric.com/\" },\n    {\n      \"@type\": \"FAQPage\",\n      \"mainEntity\": [\n        { \"@type\": \"Question\", \"name\": \"What is Wild Willows?\", \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"Wild Willows is a cozy nature-restoration life sim. You set up camp at the edge of a damaged nature preserve, then gather materials, craft and plant real habitat, and shape the land. As each biome recovers, real animal species find their way home.\" } },\n        { \"@type\": \"Question\", \"name\": \"Is Wild Willows free?\", \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"There is a free demo you can play right in your browser. The full game is a one-time purchase on the Mac App Store and on itch.io.\" } },\n        { \"@type\": \"Question\", \"name\": \"What platforms is it on?\", \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"The full game is on the Mac App Store (macOS) and on itch.io for macOS, Windows, and Linux. A free browser demo is also on the itch.io page.\" } },\n        { \"@type\": \"Question\", \"name\": \"What languages does Wild Willows support?\", \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"English and Spanish. You can switch language on the title screen or in Settings at any time.\" } },\n        { \"@type\": \"Question\", \"name\": \"Does Wild Willows have accessibility options?\", \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"Yes. There is a reduce-motion setting, colorblind palettes (red-green, blue-yellow, and high-contrast monochrome), a dyslexia-friendly font, and adjustable text size.\" } },\n        { \"@type\": \"Question\", \"name\": \"Is there any combat or a way to lose?\", \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"No. There is no combat, no enemies, and no way to fail. Animals are observed and welcomed home, never hunted or lost, and nothing ever dies.\" } },\n        { \"@type\": \"Question\", \"name\": \"Is Wild Willows family-friendly?\", \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"Yes. It is gentle, non-violent, and educational, and is rated 9+ on the App Store.\" } },\n        { \"@type\": \"Question\", \"name\": \"Do I need an internet connection?\", \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"No. The game is fully playable offline, with no account and no sign-in required.\" } }\n      ]\n    }\n  ]\n}\n</script>\n\n<style>\n:root{\n  --paper:#faf5e8; --paper2:#f0e8d4; --cream:#fffdf6; --ink:#3a3a2c; --ink-soft:#6f6e5c;\n  --green:#4a7c59; --green-deep:#3d6749; --green-2:#7cb564; --rose:#b5707a; --gold:#c9913f;\n  --line:#e2d8bd; --dark:#26301f; --dark2:#33502f; --radius:18px;\n  --shadow:0 14px 40px rgba(43,51,33,.18); --shadow-sm:0 6px 18px rgba(43,51,33,.12);\n  --display:'Fredoka','Trebuchet MS',sans-serif; --body:'Quicksand','Avenir','Segoe UI',sans-serif;\n}\n*{box-sizing:border-box}\nhtml{scroll-behavior:smooth}\nbody{margin:0;font-family:var(--body);font-weight:500;color:var(--ink);background:var(--paper);line-height:1.6;-webkit-font-smoothing:antialiased;overflow-x:hidden}\nh1,h2,h3{font-family:var(--display);font-weight:600;line-height:1.15;margin:0 0 .5rem;color:var(--green-deep)}\nh1{font-size:clamp(2.5rem,7vw,4.6rem);color:var(--cream)}\nh2{font-size:clamp(1.6rem,4vw,2.5rem)}\nh3{font-size:1.24rem}\np{margin:0 0 1rem}\na{color:var(--green-deep);text-decoration:none}\nimg{max-width:100%}\n.wrap{max-width:1140px;margin:0 auto;padding:0 1.2rem}\n.eyebrow{font-family:var(--display);font-weight:600;letter-spacing:.06em;text-transform:uppercase;font-size:.8rem;color:var(--green);margin:0 0 .5rem}\nsvg{display:block}\n\n.nav{position:sticky;top:0;z-index:20;background:rgba(38,48,31,.94);backdrop-filter:blur(8px);border-bottom:1px solid rgba(255,255,255,.08)}\n.nav .wrap{display:flex;align-items:center;gap:1rem;height:60px}\n.brand{display:flex;align-items:center;gap:.5rem;font-family:var(--display);font-weight:600;font-size:1.18rem;color:var(--cream)}\n.brand svg{width:28px;height:28px;flex:none}\n.nav .links{margin-left:auto;display:flex;gap:1.3rem;align-items:center}\n.nav .links a{color:#e7efdd;font-weight:600;font-size:.96rem}\n.nav .links a:hover{color:#fff}\n@media(max-width:720px){.nav .links a.hide-sm{display:none}}\n\n.btn{display:inline-flex;align-items:center;justify-content:center;gap:.5rem;font-family:var(--display);font-weight:600;font-size:1rem;\n  padding:.72rem 1.25rem;border-radius:999px;border:2px solid transparent;cursor:pointer;transition:transform .12s ease,background .12s ease}\n.btn:hover{transform:translateY(-2px)}\n.btn svg{width:17px;height:17px;fill:none;stroke:currentColor;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round}\n.btn-primary{background:var(--green);color:#fff;box-shadow:var(--shadow-sm)}\n.btn-primary:hover{background:var(--green-deep);color:#fff}\n.btn-ghost{background:rgba(255,255,255,.1);color:#fff;border-color:rgba(255,255,255,.42)}\n.btn-ghost:hover{background:rgba(255,255,255,.2);color:#fff}\n.btn-light{background:var(--cream);color:var(--green-deep);box-shadow:var(--shadow-sm)}\n.cta-row{display:flex;flex-wrap:wrap;gap:.7rem;align-items:center}\n\n.ico{display:inline-flex;color:var(--green)}\n.ico svg{width:28px;height:28px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}\n\n.hero{position:relative;background:linear-gradient(180deg,#20301c 0%,#324528 45%,#5c7a3f 100%);color:#eef3e6;overflow:hidden}\n.hero:after{content:\"\";position:absolute;left:0;right:0;bottom:-1px;height:64px;background:radial-gradient(120% 100% at 50% 100%,var(--paper) 40%,transparent 41%)}\n.hero .wrap{position:relative;z-index:2;padding:3.2rem 1.2rem 4.4rem;text-align:center}\n.hero p.lead{font-size:clamp(1.1rem,2.4vw,1.38rem);color:#dce7cf;max-width:44rem;margin:.4rem auto 1.5rem}\n.hero .cta-row{justify-content:center}\n.hero-shot{margin:2.2rem auto 0;max-width:940px;width:100%;height:auto;display:block;border-radius:var(--radius);border:5px solid rgba(255,255,255,.7);box-shadow:0 24px 60px rgba(0,0,0,.4)}\n\nsection{padding:3.6rem 0}\n.section-head{text-align:center;max-width:44rem;margin:0 auto 2.2rem}\n.section-head p{color:var(--ink-soft);font-size:1.06rem}\n.band{background:var(--paper2)}\n.pitch{max-width:48rem;margin:0 auto;text-align:center}\n.pitch p{font-size:1.14rem;color:var(--ink)}\n\n/* soundtrack player */\n.soundtrack{padding-top:2.6rem;padding-bottom:2.6rem}\n.player{max-width:640px;margin:0 auto;display:flex;align-items:center;gap:1.3rem;background:linear-gradient(135deg,#33502f,#26301f);color:#eef3e6;border-radius:var(--radius);padding:1.4rem 1.6rem;box-shadow:var(--shadow)}\n.play-btn{flex:none;width:66px;height:66px;border-radius:50%;border:none;cursor:pointer;background:var(--cream);color:var(--green-deep);display:flex;align-items:center;justify-content:center;box-shadow:var(--shadow-sm);transition:transform .12s ease}\n.play-btn:hover{transform:scale(1.05)}\n.play-btn svg{width:30px;height:30px}\n.play-btn .i-pause{display:none}\n.play-btn.playing .i-play{display:none}\n.play-btn.playing .i-pause{display:flex}\n.player-info{flex:1;min-width:0}\n.player-info .eyebrow{color:#a9c79a;margin:0 0 .15rem}\n.player-info h3{color:#fff;margin:0 0 .6rem;font-size:1.15rem}\n.bar{height:8px;border-radius:999px;background:rgba(255,255,255,.18);cursor:pointer;overflow:hidden}\n.bar-fill{height:100%;width:0;background:var(--green-2);border-radius:999px;transition:width .1s linear}\n.times{display:flex;justify-content:space-between;font-size:.82rem;color:#c3d2b5;margin-top:.4rem}\n@media(max-width:520px){.player{flex-direction:column;text-align:center}.player-info{width:100%}}\n\n.gallery{display:grid;grid-template-columns:1fr;gap:1.4rem}\n@media(min-width:760px){.gallery{grid-template-columns:1fr 1fr}}\n.shot{background:var(--cream);border:1px solid var(--line);border-radius:var(--radius);overflow:hidden;box-shadow:var(--shadow-sm)}\n.shot img{width:100%;height:auto;display:block;border-bottom:1px solid var(--line);background:var(--paper2)}\n.shot .cap{padding:1.05rem 1.25rem 1.25rem}\n.shot h3{margin:0 0 .25rem;color:var(--green-deep)}\n.shot p{margin:0;color:var(--ink-soft);font-size:.98rem}\n\n.everyone{display:grid;grid-template-columns:1fr 1fr;gap:1.3rem}\n@media(max-width:760px){.everyone{grid-template-columns:1fr}}\n.panel{background:var(--cream);border:1px solid var(--line);border-radius:var(--radius);padding:1.6rem 1.5rem;box-shadow:var(--shadow-sm)}\n.panel .ico svg{width:32px;height:32px}\n.panel h3{margin:.5rem 0 .4rem;color:var(--green-deep)}\n.panel ul{margin:.4rem 0 0;padding:0;list-style:none}\n.panel li{display:flex;align-items:flex-start;gap:.55rem;padding:.22rem 0;color:var(--ink)}\n.panel li svg{flex:none;width:19px;height:19px;margin-top:.18rem;fill:none;stroke:var(--green-2);stroke-width:2.2;stroke-linecap:round;stroke-linejoin:round}\n.langline{display:inline-flex;gap:.5rem;margin-top:.5rem}\n.chip{font-weight:600;color:var(--green-deep);background:#eaf1e2;border:1px solid var(--line);padding:.28rem .8rem;border-radius:999px;font-size:.95rem}\n\n.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:1.1rem}\n.card{background:var(--cream);border:1px solid var(--line);border-radius:var(--radius);padding:1.35rem 1.3rem;box-shadow:var(--shadow-sm)}\n.card h3{margin:.6rem 0 .3rem;color:var(--green-deep)}\n.card p{color:var(--ink-soft);margin:0;font-size:.97rem}\n\n.faq{max-width:48rem;margin:0 auto}\ndetails{background:var(--cream);border:1px solid var(--line);border-radius:14px;padding:.1rem 1.2rem;margin:0 0 .7rem;box-shadow:var(--shadow-sm)}\nsummary{font-family:var(--display);font-weight:600;font-size:1.06rem;color:var(--green-deep);cursor:pointer;padding:.95rem 0;list-style:none;display:flex;justify-content:space-between;align-items:center;gap:1rem}\nsummary::-webkit-details-marker{display:none}\nsummary:after{content:\"+\";font-size:1.4rem;color:var(--green-2);transition:transform .2s}\ndetails[open] summary:after{transform:rotate(45deg)}\ndetails p{color:var(--ink-soft);margin:0 0 1rem}\n\n.final{background:linear-gradient(180deg,#33502f,#26301f);color:#eef3e6;text-align:center}\n.final h2{color:#fff}\n.final p{color:#dce7cf;max-width:38rem;margin:0 auto 1.6rem}\n.final .cta-row{justify-content:center}\n\nfooter{background:var(--dark);color:#b9c4ab;padding:2.3rem 0;font-size:.92rem}\nfooter .wrap{display:flex;flex-wrap:wrap;gap:1rem 2rem;align-items:center;justify-content:space-between}\nfooter .brand svg{width:26px;height:26px}\nfooter a{color:#d7e0c8}\nfooter a:hover{color:#fff}\nfooter .foot-links{display:flex;gap:1.2rem;flex-wrap:wrap}\n</style>\n</head>\n<body>\n\n<nav class=\"nav\"><div class=\"wrap\">\n  <a class=\"brand\" href=\"#top\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"11\" fill=\"#4a7c59\"/><path d=\"M7 17C7 10.5 11 7.5 17 7.2c.3 6-2.7 10-10 9.8\" fill=\"#d8eec2\"/></svg> Wild Willows</a>\n  <div class=\"links\">\n    <a class=\"hide-sm\" href=\"#gallery\">Screenshots</a>\n    <a class=\"hide-sm\" href=\"#everyone\">Accessibility</a>\n    <a class=\"hide-sm\" href=\"#faq\">FAQ</a>\n    <a class=\"btn btn-primary\" href=\"#get\">Get the game</a>\n  </div>\n</div></nav>\n\n<header class=\"hero\" id=\"top\"><div class=\"wrap\">\n  <h1>Wild Willows</h1>\n  <p class=\"lead\">A cozy nature-restoration game. Bring a broken wild place back to life — one plant, one pond, one animal at a time.</p>\n  <div class=\"cta-row\">\n    <a class=\"btn btn-light\" href=\"https://apps.apple.com/us/app/wild-willows/id6787300760?mt=12\" rel=\"noopener\">Mac App Store</a>\n    <a class=\"btn btn-primary\" href=\"https://bai13y.itch.io/wild-willows\" rel=\"noopener\">Get it on itch.io</a>\n    <a class=\"btn btn-ghost\" href=\"https://bai13y.itch.io/wild-willows\" rel=\"noopener\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M7 5.4v13.2L18 12z\" fill=\"currentColor\" stroke=\"none\"/></svg> Play the free demo</a>\n  </div>\n  <img class=\"hero-shot\" width=\"1160\" height=\"725\" fetchpriority=\"high\" src=\"data:image/webp;base64,\" alt=\"Gameplay in Wild Willows: a recovering wetland with ponds, reeds, trees and returning birds, with a panel showing the biome at 81% health.\">\n</div></header>\n\n<main>\n\n<section class=\"band\"><div class=\"wrap pitch\">\n  <p class=\"eyebrow\">A quiet kind of adventure</p>\n  <h2>Restore the wild, at your own pace</h2>\n  <p>You've set up camp at the edge of a damaged nature preserve. Gather fallen branches, reeds, clay and stone; craft and plant real habitat; then shape the land — dig soil beds, pour ponds, carve rivers, and watch the ground green over. As a place becomes whole, real animals find their way home. There are no timers, no enemies, and no way to lose. Just a gentle, hopeful loop of making somewhere better.</p>\n</div></section>\n\n<section class=\"soundtrack\" id=\"soundtrack\"><div class=\"wrap\">\n  <div class=\"player\">\n    <button class=\"play-btn\" id=\"ppBtn\" type=\"button\" aria-label=\"Play the Wild Willows theme\">\n      <span class=\"i-play\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M8 5v14l11-7z\" fill=\"currentColor\" stroke=\"none\"/></svg></span><span class=\"i-pause\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><rect x=\"7\" y=\"5\" width=\"3.6\" height=\"14\" rx=\"1.1\" fill=\"currentColor\" stroke=\"none\"/><rect x=\"13.4\" y=\"5\" width=\"3.6\" height=\"14\" rx=\"1.1\" fill=\"currentColor\" stroke=\"none\"/></svg></span>\n    </button>\n    <div class=\"player-info\">\n      <p class=\"eyebrow\">Original soundtrack by Jon Licht</p>\n      <h3>Wild Willows — Main Theme</h3>\n      <div class=\"bar\" id=\"ppBar\" role=\"progressbar\" aria-label=\"Theme progress\"><div class=\"bar-fill\" id=\"ppFill\"></div></div>\n      <div class=\"times\"><span id=\"ppCur\">0:00</span><span id=\"ppDur\">3:00</span></div>\n    </div>\n    <audio id=\"ppAudio\" src=\"/theme.mp3\" preload=\"none\"></audio>\n  </div>\n</div></section>\n\n<section id=\"gallery\"><div class=\"wrap\">\n  <div class=\"section-head\">\n    <p class=\"eyebrow\">Take a look</p>\n    <h2>Gather, craft, and welcome them home</h2>\n    <p>A simple, satisfying loop with a surprising amount of depth underneath.</p>\n  </div>\n  <div class=\"gallery\">\n    <figure class=\"shot\"><img loading=\"lazy\" width=\"1160\" height=\"725\" src=\"data:image/webp;base64,\" alt=\"The Preserve map in Wild Willows showing six biomes as progress rings, each with a restoration goal.\"><figcaption class=\"cap\"><h3>Six living biomes</h3><p>Restore a meadow, forest, wetland, desert, alpine range and shore — each with its own Health and ecological Balance.</p></figcaption></figure>\n    <figure class=\"shot\"><img loading=\"lazy\" width=\"1160\" height=\"725\" src=\"data:image/webp;base64,\" alt=\"The crafting menu in Wild Willows listing habitat recipes and the materials each needs.\"><figcaption class=\"cap\"><h3>Craft &amp; build anywhere</h3><p>150 recipes and 179 habitat pieces, crafted straight from your basket and chests — no workbench required.</p></figcaption></figure>\n    <figure class=\"shot\"><img loading=\"lazy\" width=\"1160\" height=\"725\" src=\"data:image/webp;base64,\" alt=\"The field guide in Wild Willows showing real forest animals with their diet, shelter and role.\"><figcaption class=\"cap\"><h3>150 real animals</h3><p>Real species with real diets, shelters and facts. They return only when the habitat truly supports them.</p></figcaption></figure>\n    <figure class=\"shot\"><img loading=\"lazy\" width=\"1160\" height=\"725\" src=\"data:image/webp;base64,\" alt=\"A biome food web in Wild Willows grouping animals by predators, omnivores and herbivores.\"><figcaption class=\"cap\"><h3>Complete the food web</h3><p>Predators wait for their prey. Fill out each biome's web to bring it into true balance.</p></figcaption></figure>\n    <figure class=\"shot\"><img loading=\"lazy\" width=\"1160\" height=\"725\" src=\"data:image/webp;base64,\" alt=\"The Weather and Seasons guide in Wild Willows with a forecast across the preserve.\"><figcaption class=\"cap\"><h3>Real weather &amp; seasons</h3><p>Science-grounded weather and seasons roll through each biome — with a live forecast and rare, gatherable materials.</p></figcaption></figure>\n    <figure class=\"shot\"><img loading=\"lazy\" width=\"1160\" height=\"725\" src=\"data:image/webp;base64,\" alt=\"Foraging in an autumn forest in Wild Willows, gathering water, morning dew and branches.\"><figcaption class=\"cap\"><h3>Forage through the seasons</h3><p>What you can gather shifts with the weather and the season — some materials only appear in rain, fog, snow or heat.</p></figcaption></figure>\n    <figure class=\"shot\"><img loading=\"lazy\" width=\"1160\" height=\"725\" src=\"data:image/webp;base64,\" alt=\"The caretaker creator in Wild Willows with skin, hair, outfit and hat options.\"><figcaption class=\"cap\"><h3>Make your caretaker</h3><p>Design your caretaker's skin, hair, build, outfit and hat before you set out.</p></figcaption></figure>\n    <figure class=\"shot\"><img loading=\"lazy\" width=\"1160\" height=\"725\" src=\"data:image/webp;base64,\" alt=\"Willow Meadow in Wild Willows with the player's camp tent, home, flowers and a chest.\"><figcaption class=\"cap\"><h3>Build &amp; decorate a home</h3><p>Raise a Log Cabin, Meadow Cottage or Stone Hearth, step inside, and furnish it with cozy comforts.</p></figcaption></figure>\n    <figure class=\"shot\"><img loading=\"lazy\" width=\"1160\" height=\"725\" src=\"data:image/webp;base64,\" alt=\"The custom goals panel in Wild Willows for choosing what to work toward.\"><figcaption class=\"cap\"><h3>Play it your way</h3><p>Set your own goals, work through gentle daily tasks, and earn 50 achievements for the milestones that matter to you.</p></figcaption></figure>\n  </div>\n</div></section>\n\n<section class=\"band\" id=\"everyone\"><div class=\"wrap\">\n  <div class=\"section-head\"><p class=\"eyebrow\">For everyone</p><h2>Made to be played by more people</h2></div>\n  <div class=\"everyone\">\n    <div class=\"panel\">\n      <span class=\"ico\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><line x1=\"3.2\" y1=\"12\" x2=\"20.8\" y2=\"12\"/><path d=\"M12 3c2.6 2.4 4 5.6 4 9s-1.4 6.6-4 9c-2.6-2.4-4-5.6-4-9s1.4-6.6 4-9z\"/></svg></span>\n      <h3>Play in your language</h3>\n      <p>Wild Willows is fully translated — switch on the title screen or in Settings anytime.</p>\n      <div class=\"langline\"><span class=\"chip\">English</span><span class=\"chip\">Español</span></div>\n    </div>\n    <div class=\"panel\">\n      <span class=\"ico\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"4.4\" r=\"1.7\"/><path d=\"M4.6 8.4c2.4.9 4.9 1.3 7.4 1.3s5-.4 7.4-1.3\"/><path d=\"M12 9.7V14M12 14l-2.7 6M12 14l2.7 6\"/></svg></span>\n      <h3>Accessibility built in</h3>\n      <ul>\n        <li><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.6l4.2 4.2L19 7\"/></svg> Reduce-motion mode for calmer visuals</li>\n        <li><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.6l4.2 4.2L19 7\"/></svg> Colorblind palettes — red-green, blue-yellow &amp; high-contrast</li>\n        <li><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.6l4.2 4.2L19 7\"/></svg> Dyslexia-friendly font (OpenDyslexic)</li>\n        <li><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.6l4.2 4.2L19 7\"/></svg> Adjustable text size</li>\n      </ul>\n    </div>\n  </div>\n</div></section>\n\n<section><div class=\"wrap\">\n  <div class=\"section-head\"><p class=\"eyebrow\">Why you'll love it</p><h2>Cozy, all the way down</h2></div>\n  <div class=\"grid\">\n    <div class=\"card\"><span class=\"ico\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M20.8 5.7a5 5 0 0 0-7.1 0L12 7.4l-1.7-1.7a5 5 0 1 0-7.1 7.1L12 21l8.8-8.2a5 5 0 0 0 0-7.1z\"/></svg></span><h3>Gentle by design</h3><p>No combat, no enemies, no fail state. Animals are welcomed home, never harmed — nothing ever dies.</p></div>\n    <div class=\"card\"><span class=\"ico\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M17.5 19a4.5 4.5 0 0 0 .8-8.9A6 6 0 0 0 7 8\"/><path d=\"M6.7 10.1A4.5 4.5 0 0 0 6.5 19H15\"/><line x1=\"3\" y1=\"3\" x2=\"21\" y2=\"21\"/></svg></span><h3>Truly offline</h3><p>No account, no sign-in, no internet needed. Your world lives on your own device.</p></div>\n    <div class=\"card\"><span class=\"ico\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><line x1=\"5.6\" y1=\"5.6\" x2=\"18.4\" y2=\"18.4\"/></svg></span><h3>No ads, ever</h3><p>No ads, no in-app purchases, no loot boxes, no tracking. Buy it once and play.</p></div>\n    <div class=\"card\"><span class=\"ico\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 6.6C10.5 5.4 8.3 4.9 4 5.1v13c4.3-.2 6.5.3 8 1.5 1.5-1.2 3.7-1.7 8-1.5v-13c-4.3-.2-6.5.3-8 1.5z\"/><line x1=\"12\" y1=\"6.6\" x2=\"12\" y2=\"20\"/></svg></span><h3>Quietly educational</h3><p>150 real species and a plain-language weather &amp; seasons guide grounded in credible sources.</p></div>\n    <div class=\"card\"><span class=\"ico\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 3a9 9 0 1 0 0 18c1.2 0 2-.9 2-2 0-1.2-1-1.9-1-2.9 0-.6.5-1.1 1.1-1.1H16a5 5 0 0 0 5-5c0-3.8-4-6-9-6z\"/><circle cx=\"7.6\" cy=\"11\" r=\"1.1\"/><circle cx=\"10\" cy=\"7.4\" r=\"1.1\"/><circle cx=\"14.6\" cy=\"7.4\" r=\"1.1\"/></svg></span><h3>Handmade feel</h3><p>Soft, friendly art generated from simple shapes — every animal reads as its own creature.</p></div>\n    <div class=\"card\"><span class=\"ico\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"9\" cy=\"7\" r=\"3.1\"/><path d=\"M2.5 20v-1.4a4 4 0 0 1 4-4H11a4 4 0 0 1 4 4V20\"/><path d=\"M16 4.2a3.1 3.1 0 0 1 0 5.9M21.5 20v-1.4a4 4 0 0 0-3-3.8\"/></svg></span><h3>Family-friendly</h3><p>Gentle, non-violent play. Rated 9+ on the App Store — calm to wind down with, deep enough to keep you.</p></div>\n  </div>\n</div></section>\n\n<section class=\"band\" id=\"faq\"><div class=\"wrap\">\n  <div class=\"section-head\"><p class=\"eyebrow\">Good to know</p><h2>Frequently asked questions</h2></div>\n  <div class=\"faq\">\n    <details open><summary>What is Wild Willows?</summary><p>A cozy nature-restoration life sim. You set up camp at the edge of a damaged nature preserve, then gather materials, craft and plant real habitat, and shape the land. As each biome recovers, real animal species find their way home.</p></details>\n    <details><summary>Is Wild Willows free?</summary><p>There's a free demo you can play right in your browser on the itch.io page. The full game is a one-time purchase on the Mac App Store and on itch.io.</p></details>\n    <details><summary>What platforms is it on?</summary><p>The full game is on the Mac App Store for macOS, and on itch.io for macOS, Windows, and Linux. A free browser demo lives on the itch.io page too.</p></details>\n    <details><summary>What languages does it support?</summary><p>English and Spanish. You can switch language on the title screen or in Settings at any time.</p></details>\n    <details><summary>Does it have accessibility options?</summary><p>Yes — a reduce-motion setting, colorblind palettes (red-green, blue-yellow, and high-contrast monochrome), a dyslexia-friendly font, and adjustable text size.</p></details>\n    <details><summary>Is there any combat or a way to lose?</summary><p>No. There's no combat, no enemies, and no way to fail. Animals are observed and welcomed home — never hunted, captured, or lost — and nothing ever dies.</p></details>\n    <details><summary>Is it family-friendly?</summary><p>Yes — it's gentle, non-violent and educational, and rated 9+ on the App Store.</p></details>\n    <details><summary>Do I need an internet connection?</summary><p>No. The game is fully playable offline, with no account and no sign-in.</p></details>\n  </div>\n</div></section>\n\n<section class=\"final\" id=\"get\"><div class=\"wrap\">\n  <h2>Ready to bring the wild home?</h2>\n  <p>Start with the free browser demo, or pick it up on your platform of choice.</p>\n  <div class=\"cta-row\">\n    <a class=\"btn btn-light\" href=\"https://apps.apple.com/us/app/wild-willows/id6787300760?mt=12\" rel=\"noopener\">Mac App Store</a>\n    <a class=\"btn btn-primary\" href=\"https://bai13y.itch.io/wild-willows\" rel=\"noopener\">Get it on itch.io</a>\n    <a class=\"btn btn-ghost\" href=\"https://bai13y.itch.io/wild-willows\" rel=\"noopener\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M7 5.4v13.2L18 12z\" fill=\"currentColor\" stroke=\"none\"/></svg> Play the free demo</a>\n  </div>\n</div></section>\n\n</main>\n\n<footer><div class=\"wrap\">\n  <div class=\"brand\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"11\" fill=\"#4a7c59\"/><path d=\"M7 17C7 10.5 11 7.5 17 7.2c.3 6-2.7 10-10 9.8\" fill=\"#d8eec2\"/></svg> Wild Willows</div>\n  <div class=\"foot-links\">\n    <a href=\"https://apps.apple.com/us/app/wild-willows/id6787300760?mt=12\" rel=\"noopener\">App Store</a>\n    <a href=\"https://bai13y.itch.io/wild-willows\" rel=\"noopener\">itch.io</a>\n    <a href=\"/privacy.html\">Privacy</a>\n    <a href=\"/age-rating.html\">Age suitability</a>\n    <a href=\"/support.html\">Support</a>\n  </div>\n  <div>Made by Bailey Dunning &middot; Music &amp; sound by Jon Licht &middot; &copy; 2026</div>\n</div></footer>\n\n<script>\n(function(){\n  var a=document.getElementById('ppAudio'),b=document.getElementById('ppBtn'),\n      bar=document.getElementById('ppBar'),fill=document.getElementById('ppFill'),\n      cur=document.getElementById('ppCur'),dur=document.getElementById('ppDur');\n  if(!a||!b)return;\n  function fmt(t){t=Math.floor(t||0);var m=Math.floor(t/60),s=t%60;return m+':'+(s<10?'0':'')+s;}\n  function set(p){b.classList.toggle('playing',p);b.setAttribute('aria-label',p?'Pause the Wild Willows theme':'Play the Wild Willows theme');}\n  b.addEventListener('click',function(){a.paused?a.play():a.pause();});\n  a.addEventListener('play',function(){set(true);});\n  a.addEventListener('pause',function(){set(false);});\n  a.addEventListener('ended',function(){set(false);fill.style.width='0%';cur.textContent='0:00';});\n  a.addEventListener('loadedmetadata',function(){if(isFinite(a.duration))dur.textContent=fmt(a.duration);});\n  a.addEventListener('timeupdate',function(){if(a.duration){fill.style.width=(a.currentTime/a.duration*100)+'%';cur.textContent=fmt(a.currentTime);}});\n  bar.addEventListener('click',function(e){var r=bar.getBoundingClientRect();if(a.duration)a.currentTime=Math.max(0,Math.min(1,(e.clientX-r.left)/r.width))*a.duration;});\n})();\n</script>\n</body>\n</html>";

